def main():
    global HAAD_TOPICS, UHS_TOPICS, PLAB_TOPICS
    HAAD_TOPICS = HAAD_TOPICS[:100]
    UHS_TOPICS = UHS_TOPICS[:100]
    PLAB_TOPICS = PLAB_TOPICS[:100]

    print(f"Total HAAD topics: {len(HAAD_TOPICS)}")
    print(f"Total UHS topics: {len(UHS_TOPICS)}")
    print(f"Total PLAB topics: {len(PLAB_TOPICS)}")

    assert len(HAAD_TOPICS) == 100, f"Expected 100 HAAD topics, got {len(HAAD_TOPICS)}"
    assert len(UHS_TOPICS) == 100, f"Expected 100 UHS topics, got {len(UHS_TOPICS)}"
    assert len(PLAB_TOPICS) == 100, f"Expected 100 PLAB topics, got {len(PLAB_TOPICS)}"

    for title, subj, sys_name, snip, g_name, g_url in HAAD_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in UHS_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in PLAB_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    out_path = os.path.join(os.path.dirname(__file__), "mega41_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 41 Topics Part B\n")
        f.write("# HAAD / DHA (100 topics) + UHS MBBS (100 topics) + PLAB / UKMLA (100 topics)\n\n")
        f.write(f"HAAD_TOPICS = {repr(HAAD_TOPICS)}\n\n")
        f.write(f"UHS_TOPICS = {repr(UHS_TOPICS)}\n\n")
        f.write(f"PLAB_TOPICS = {repr(PLAB_TOPICS)}\n")
    print(f"Successfully generated {out_path}!")

if __name__ == "__main__":
    main()
